def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 484 Pharmacy Technician II ----
H('484.d.1.A',3,"A technician answering a phone call from an anxious caregiver uses a calm tone, avoids slang, and shows courtesy. This is a respectful and professional:","attitude",["hairstyle","salary","inventory"],"Professional attitude shapes every communication.")
H('484.d.1.A',4,"Gossiping about a patient's medicines in the break room breaks the professional standard of:","confidentiality",["punctuality","creativity","speed"],"Patient information must stay private.")
H('484.d.1.B',3,"For a patient who is blind, a technician should explain the label contents by:","reading the label aloud",["pointing at the label","handing over a printout only","waving at the bottle"],"Adapt the method to the patient's need.")
H('484.d.1.B',4,"A child patient's parent asks about a liquid medicine. The technician should speak to the parent as the:","caregiver who gives the doses",["pharmacy owner","insurance agent","delivery driver"],"Caregivers need clear instructions.")
H('484.d.1.C',3,"A technician who relays a doctor's office question to the pharmacist is supporting communication between the pharmacy and the:","prescriber's office",["parking lot","bank","fire station"],"Technicians bridge stakeholders.")
H('484.d.1.C',4,"When an insurance plan rejects a claim, the technician helps the pharmacist communicate with the plan, the patient, and the:","prescriber",["landlord","neighbor","reporter"],"Several stakeholders may need contact.")
H('484.d.2.A',3,"To interpret a medication order correctly, a technician reads the drug name, strength, route, and:","frequency",["color of ink","pen brand","font size"],"Orders list how often to give a drug.")
H('484.d.2.A',4,"A prescription reads 'amoxicillin 500 mg cap, 1 cap po tid.' The abbreviation po means:","by mouth",["by injection","under the tongue","in the eye"],"po = per os, by mouth.")
H('484.d.2.B',3,"A pharmacy sends the doctor's office a written request asking to change a drug because it is out of stock. This document is pharmacy:","correspondence",["marketing","payroll","inventory count"],"Correspondence is written communication.")
H('484.d.2.B',4,"A medication administration record in a hospital documents each dose given and the:","time it was given",["patient's hobby","nurse's phone model","room color"],"The MAR logs administration.")
H('484.d.2.C',3,"The medical term for a drug that eases pain is a(n):","analgesic",["antibiotic","antacid","anticoagulant"],"Analgesics relieve pain.")
H('484.d.2.C',4,"A pharmacy tech sees the term 'antihypertensive.' This kind of medicine is used to treat:","high blood pressure",["low blood sugar","infections","allergies"],"Hypertension means high pressure.")
H('484.d.2.D',3,"A sig reads 'i gtt OU qid.' The OU part means in:","both eyes",["the right ear","the left eye","both ears"],"OU = oculus uterque, both eyes.")
H('484.d.2.D',4,"On a sig, the code prn means to take the medicine:","only as needed",["every morning","before meals only","at bedtime only"],"prn = pro re nata, as needed.")
H('484.d.3.A',3,"Cytotoxic drugs, which can harm workers who touch them, are handled using gloves and disposed of in a container for:","hazardous drug waste",["regular trash","paper recycling","glass recycling"],"Hazardous drugs require special disposal.")
H('484.d.3.A',4,"A technician finds a spilled vial of a hazardous drug. The first action is to follow the pharmacy's:","spill procedure",["lunch schedule","sales plan","parking rules"],"Spills follow written procedures.")
H('484.d.3.B',3,"A controlled-substance prescription must include the prescriber's DEA number and the patient's:","address",["shoe size","favorite drink","hobbies"],"Controlled prescriptions have extra required details.")
H('484.d.3.B',4,"A Schedule II prescription cannot be:","refilled",["filled","signed","stored"],"Schedule II drugs have no refills.")
H('484.d.3.C',3,"Controlled substances in the pharmacy are stored in a:","locked, secure area",["open bin by the door","customer waiting area","front window display"],"Security prevents theft and diversion.")
H('484.d.3.C',4,"When a shipment of controlled substances arrives, the receiving record must be checked and signed by a:","pharmacist",["delivery driver only","visitor","customer"],"Only authorized staff check CII receipts.")
H('484.d.3.D',3,"Heroin is classified as a Schedule I drug because it has a high potential for abuse and:","no accepted medical use",["many approved uses","no side effects","low risk"],"Schedule I has no accepted medical use.")
H('484.d.3.D',4,"Which schedule has the lowest abuse potential among the five?","Schedule V",["Schedule I","Schedule II","Schedule III"],"Schedule V is the lowest.")
H('484.d.3.E',3,"Medicines containing pseudoephedrine are kept behind the counter because they can be misused to make illegal:","methamphetamine",["vitamins","antibiotics","insulin"],"The Combat Meth Epidemic Act limits sales.")
H('484.d.3.E',4,"Federal law requires a store to record each pseudoephedrine buyer's name, ID, and the:","amount purchased",["buyer's weight","car color","favorite brand of soap"],"Sales are logged and limited.")
H('484.d.3.F',3,"When a manufacturer pulls an unsafe batch of tablets from the market, the pharmacy must remove the product listed in the:","recall notice",["menu","sales flyer","coupon"],"Recalls identify affected lots.")
H('484.d.3.F',4,"After removing recalled stock, the pharmacy records how many units were found and:","how they were returned or destroyed",["the day's weather","the clerk's age","the shelf color"],"Recalls require documentation.")
H('484.d.3.G',3,"Tasks a technician may legally perform are limited by the state's:","scope of practice",["parking policy","uniform code only","sales target"],"Scope of practice defines allowed duties.")
H('484.d.3.G',4,"A technician is asked to counsel a patient on side effects. Because counseling is a pharmacist duty, the technician should:","refer the patient to the pharmacist",["answer anyway","guess the answer","skip the question"],"Stay within scope.")
H('484.d.4.A',3,"Lipitor is a brand-name drug that lowers cholesterol. Its drug class is the:","statin",["antibiotic","antihistamine","diuretic"],"Atorvastatin lowers cholesterol.")
H('484.d.4.A',4,"Metformin is used for the indication of:","type 2 diabetes",["asthma","high blood pressure","epilepsy"],"Metformin lowers blood glucose.")
H('484.d.4.B',3,"Taking warfarin with some other drugs can raise the risk of:","bleeding",["sneezing","hair loss only","sleepiness only"],"Warfarin interactions affect clotting.")
H('484.d.4.B',4,"A drug that should not be used with another because the combination is dangerous has a(n):","major interaction",["trivial flavor","expiration","brand name"],"Major interactions are flagged for the pharmacist.")
H('484.d.4.C',3,"A drug with a narrow therapeutic index requires blood levels to be checked because a small change in dose can cause:","toxicity or treatment failure",["a new flavor","a change in tablet color only","faster shipping"],"NTI drugs have small safety margins.")
H('484.d.4.C',4,"Which of these is commonly considered an NTI drug?","phenytoin",["vitamin C","acetaminophen","loratadine"],"Phenytoin has a narrow range.")
H('484.d.4.D',3,"A technician looking for the legal standards for compounding would use the United States:","Pharmacopeia",["Atlas","Census","Encyclopedia"],"USP lists compounding standards.")
H('484.d.4.D',4,"A quick online drug reference is helpful, but the technician must make sure the source is current and:","reliable",["colorful","free of numbers","loud"],"Check reliability.")
H('484.d.5.A',3,"A prescription is missing the patient's date of birth. The technician should note the item as:","incomplete",["finished","refillable","free"],"Required items must be present.")
H('484.d.5.A',4,"Besides the drug name and strength, a medication order for a hospital patient must show the route and the:","prescriber's signature or authentication",["patient's hairstyle","pharmacy's slogan","tech's initials only"],"Orders must be authenticated.")
H('484.d.5.B',3,"For a patient who prefers written information, a technician can provide a printed sheet in a language the patient:","understands",["dislikes","never uses","mispronounces"],"Choose an appropriate modality.")
H('484.d.5.B',4,"Using a video relay interpreter for a deaf patient is an example of choosing the right communication:","modality",["receipt","coupon","password"],"The method must fit the patient.")
H('484.d.5.C',3,"Gathering a patient's address, phone number, and insurance information is collecting:","demographic information",["clinical results","lab values","chemical formulas"],"Demographics identify the patient.")
H('484.d.5.C',4,"Recording a patient's height, weight, and allergies is entering:","clinical information",["advertising","billing codes","stock numbers"],"Clinical data support dosing and safety.")
H('484.d.5.D',3,"Before preparing an intravenous admixture in a hood, a technician must first perform:","hand hygiene and garbing",["a coffee break","a sales call","an inventory count"],"Aseptic technique begins with hand hygiene.")
H('484.d.5.D',4,"The air in an IV compounding hood moves in a direction that carries particles away from the product. This is called:","laminar airflow",["turbulent airflow","still air","random wind"],"Laminar flow keeps product clean.")
H('484.d.5.E',3,"A patient with diabetes needs supplies to check blood glucose, which includes a meter and:","test strips",["rubber bands","bandage tape only","thermometers only"],"Strips test the sample.")
H('484.d.5.E',4,"A nebulizer is used to turn liquid medicine into a mist that the patient breathes through a:","mask or mouthpiece",["straw","syringe","bandage"],"Nebulizers deliver inhaled drugs.")
H('484.d.5.F',3,"Each medicine product has a unique 10- or 11-digit number that identifies the manufacturer and product, called the:","National Drug Code",["social number","phone code","zip code"],"NDC identifies the product.")
H('484.d.5.F',4,"If a bottle has a beyond-use date shorter than the manufacturer's expiration date, the pharmacy must follow the:","earlier date",["later date","color of the label","price tag"],"Use the shorter date.")
H('484.d.5.G',3,"Using a fresh pair of gloves for each task prevents:","cross-contamination",["gloves from selling","labels from fading","bottles from cracking"],"Changing gloves limits germs.")
H('484.d.5.G',4,"Washing hands with soap and water is preferred over sanitizer when hands are visibly:","soiled",["dry","cool","clean"],"Soap removes visible soil.")
H('484.d.6.A',3,"Insulin, heparin, and opioids are often called high-alert medications because mistakes with them can cause:","serious harm",["small delays","bad tastes","color changes"],"High-alert drugs are riskier.")
H('484.d.6.A',4,"The drug names Celebrex and Cerebyx are an example of a look-alike/sound-alike pair, so the pharmacy may store them in:","separate places",["the same bin","the front window","a personal drawer"],"Separation prevents mix-ups.")
H('484.d.6.B',3,"A label written as hydrOXYzine and hydrALAZINE uses capital letters to highlight differences. This strategy is:","Tall Man lettering",["Bold naming","Title casing","Block printing"],"Tall Man lettering helps.")
H('484.d.6.B',4,"Asking the patient to state their full name and birth date before handing over a bag is using two:","patient identifiers",["receipts","coupons","pens"],"Two identifiers confirm the right patient.")
H('484.d.6.C',3,"An order for 500 mg of a drug that is normally given in 5 mg doses is an example of a(n):","abnormal dose",["early refill","brand switch","generic substitution"],"A hundredfold dose is a red flag.")
H('484.d.6.C',4,"A prescription with an illegible handwritten dose should be:","clarified with the prescriber",["guessed","filled quickly","thrown away"],"Never guess.")
H('484.d.6.D',3,"A technician who notices a patient allergic to penicillin has a new penicillin prescription should immediately alert the:","pharmacist",["cashier","driver","customer behind them"],"Safety issues go to the pharmacist.")
H('484.d.6.D',4,"A technician sees that the dose on a pediatric prescription is far higher than the weight-based dose. The technician should:","stop and tell the pharmacist",["fill it and hope","call the insurance company","relabel it"],"Flag unusual doses.")
H('484.d.6.E',3,"An error that is caught before it reaches the patient is a:","near miss",["harm event","recall","refill"],"Near misses are caught early.")
H('484.d.6.E',4,"An unexpected harmful result from a medication given correctly is an adverse:","drug reaction",["price change","stock level","delivery"],"ADRs happen even without errors.")
H('484.d.7.A',3,"In a community pharmacy, a prescription starts with the prescriber's order, which may be handwritten, phoned in, faxed, or:","electronically prescribed",["tweeted","painted","mailed in a bottle"],"E-prescribing is common.")
H('484.d.7.A',4,"A prescription received by phone must be reduced to writing or electronic form by the:","pharmacist",["delivery driver","customer","insurance clerk"],"Only pharmacists take new oral orders.")
H('484.d.7.B',3,"Verifying a prescription includes checking the patient's name, the drug, and the:","prescriber's authority",["pharmacy's carpet","tech's lunch","bottle's color"],"Prescribers must be authorized.")
H('484.d.7.B',4,"A pharmacist can confirm an unfamiliar prescriber is legitimate by checking the prescriber's:","license and DEA registration",["taste in music","clinic's slogan","car"],"Verification prevents fraud.")
H('484.d.7.C',3,"After entering a prescription into the computer, the technician compares the entered sig with the:","original prescription",["receipt tape","calendar","weather report"],"Check entry against the source.")
H('484.d.7.C',4,"Selecting the wrong patient profile during data entry could lead to a dispensing:","error",["discount","holiday","parade"],"Profile errors are dangerous.")
H('484.d.7.D',3,"When counting tablets from a stock bottle, the technician should confirm the NDC matches the one on the:","label and the drug being dispensed",["door","uniform","paycheck"],"Match NDCs.")
H('484.d.7.D',4,"Filling a prescription for a liquid antibiotic powder requires adding the correct amount of:","water",["salt","sugar","oil"],"Reconstitution uses water.")
H('484.d.7.E',3,"Before a nurse gives an injection, the order is checked against the five rights: right patient, right drug, right dose, right route, and right:","time",["color","brand","coupon"],"The five rights prevent errors.")
H('484.d.7.E',4,"A medicine ordered 'IV' is administered:","into a vein",["by mouth","under the tongue","on the skin"],"IV = intravenous.")
H('484.d.7.F',3,"In a busy pharmacy, a prescription moves from intake to data entry, then to filling, then to pharmacist verification, and finally to:","pickup or delivery",["the shredder","the supplier","the lobby"],"Workflow ends with dispensing.")
H('484.d.7.F',4,"A prescription waiting for an insurance approval is placed in a queue called:","on hold",["finished","recalled","expired"],"Workflow queues track status.")
H('484.d.7.G',3,"A fixed amount that a patient pays at pickup for each prescription is the:","copay",["premium","deductible","tax"],"Copay is a set fee.")
H('484.d.7.G',4,"When a claim is sent to the insurer electronically and returns a response in seconds, the process is called:","online adjudication",["paper filing","manual counting","refilling"],"Adjudication decides payment.")
H('484.d.8.A',3,"A child weighs 20 kg and the order is 10 mg per kg once. The dose is:","200 mg",["30 mg","2 mg","100 mg"],"20 x 10 = 200.")
H('484.d.8.A',4,"An adult order is 15 mg per kg per day divided into 3 doses. For a 60 kg adult each dose is:","300 mg",["900 mg","45 mg","100 mg"],"15 x 60 = 900 mg/day; 900 / 3 = 300 mg.")
