H('484.d.8.G',4,"How many grams of dextrose are needed for 500 mL of a 5 percent w/v solution?","25 g",["5 g","50 g","2.5 g"],"5 g per 100 mL x 5 = 25.")
H('484.d.8.H',3,"A drug costs the pharmacy 8 dollars and sells for 12 dollars. The markup in dollars is:","4",["8","12","20"],"12 - 8 = 4.")
H('484.d.8.H',4,"A medication costs 40 dollars and the pharmacy adds a 25 percent markup. The selling price is:","50 dollars",["45 dollars","60 dollars","65 dollars"],"40 x 1.25 = 50.")
H('484.d.9.A',3,"A machine that stores and counts pills and delivers them to the pharmacist is an automated:","dispensing cabinet",["cash register","phone","printer"],"Automated cabinets store drugs.")
H('484.d.9.A',4,"Hospital nursing units use automated dispensing cabinets that log which nurse took which drug and:","when it was removed",["what they ate","who parked","the nurse's age"],"Cabinets track access.")
H('484.d.9.B',3,"Pharmacy dispensing software keeps each patient's information in a profile that includes allergies and:","medication history",["car model","pet's name","favorite song"],"Profiles aid safety.")
H('484.d.9.B',4,"If the software warns of a possible drug interaction, the technician should alert the:","pharmacist",["manager","salesperson","courier"],"Pharmacists review alerts.")
H('484.d.9.C',3,"Sending patient information by regular unsecured text message could violate:","privacy rules",["traffic laws","holiday rules","building codes"],"Texts must protect PHI.")
H('484.d.9.C',4,"When faxing a prescription transfer, the technician should use a cover sheet that includes a statement about:","confidentiality",["advertising","weather","sports"],"Cover sheets protect privacy.")
H('484.d.9.D',3,"A barcode scanner used when filling prescriptions is an example of an input:","device",["recipe","law","drug"],"Scanners input data.")
H('484.d.9.D',4,"A label printer that prints the prescription label is an example of a(n):","output device",["input device only","storage shelf","power supply"],"Printers output data.")
H('484.d.9.E',3,"A technician can look up a tablet's imprint, shape, and color using a(n):","pill identifier tool",["road map","calendar","calculator only"],"Imprint search identifies tablets.")
H('484.d.9.E',4,"When searching for drug information online, the best sources include government sites and:","professional pharmacy references",["social media posts","advertisements","gossip pages"],"Choose reliable references.")
H('484.d.10.A',3,"A pharmacy study of a new drug based on only a few patients with no comparison group has weak:","validity",["packaging","pricing","marketing"],"Small, uncontrolled studies are weak.")
H('484.d.10.A',4,"Repeating a study and getting the same results shows the study is:","reliable",["unfair","secret","expensive"],"Reliability is consistency.")
H('484.d.10.B',3,"A good place to find valid drug information is a peer-reviewed:","journal",["billboard","flyer","coupon book"],"Peer review adds quality control.")
H('484.d.10.B',4,"Before relying on an article, a technician checks the author's credentials and the publication:","date",["font","length","logo"],"Information may be outdated.")
H('484.d.10.C',3,"When using online resources in a pharmacy, a technician should never post a patient's:","personal information",["opinions on weather","favorite books","school mascot"],"Patient data must stay private.")
H('484.d.10.C',4,"A pharmacy website that asks patients to log in should use a secure connection that begins with:","https",["gossip","maybe","ftp"],"HTTPS encrypts data.")
H('484.d.10.D',3,"A website run by a drug company about its own drug may be biased because the company wants to:","sell the drug",["lose money","hide the label","close the store"],"Check for conflicts of interest.")
H('484.d.10.D',4,"To analyze whether an online article is trustworthy, a technician compares it with other:","independent sources",["advertisements","jokes","coupons"],"Cross-checking improves reliability.")
