H('484.d.10.E',4,"Technology that lets patients refill prescriptions with a smartphone app is an example of an advance in pharmacy:","convenience",["demolition","taxation","farming"],"Apps improve access.")
H('484.d.10.F',3,"A technician who wants more hands-on training could join a local community:","college program",["parade","sports team only","music band only"],"Extended learning builds skills.")
H('484.d.10.F',4,"A student can earn a pharmacy technician certification by passing an exam such as the one given by the Pharmacy Technician Certification:","Board",["Beach","Bakery","Bank"],"PTCB offers the CPhT exam.")
H('484.d.10.G',3,"Information in a journal article is stronger when the study includes a large number of:","participants",["pictures","pages","ads"],"Sample size matters.")
H('484.d.10.G',4,"When two sources about a drug disagree, the technician should ask the pharmacist and check a:","primary or tertiary reference",["social post","rumor","guess"],"Escalate and verify.")
H('484.d.11.A',3,"Some injectable drugs must be kept cold, which is storage by:","temperature",["alphabet","color","price"],"Temperature stability matters.")
H('484.d.11.A',4,"Insulin pens in use at room temperature are labeled with a shorter use period because heat and time cause the drug to:","lose potency",["gain weight","turn into water","become a tablet"],"Heat degrades biologics.")
H('484.d.11.B',3,"A pharmacist may substitute a generic drug for a brand-name drug if the two are therapeutically:","equivalent",["expensive","decorated","unrelated"],"The Orange Book lists equivalents.")
H('484.d.11.B',4,"A product with an 'AB' rating in the Orange Book is considered:","therapeutically equivalent",["unsafe","banned","experimental"],"AB means equivalent.")
H('484.d.11.C',3,"Removing expired items on a regular schedule is an inventory control practice often done:","monthly",["never","once in ten years","only at closing time of the year"],"Routine checks catch expired drugs.")
