H('484.d.11.E',3,"Federal law requires a special order form for purchasing Schedule II drugs, called DEA Form:","222",["22","2","2222"],"CII orders use Form 222.")
H('484.d.11.E',4,"State laws can require pharmacies to keep purchase records for at least:","two years",["one day","one week","one hour"],"Record retention laws vary by state.")
H('484.d.11.F',3,"The lot number, expiration date, and NDC on a delivery are checked against the:","invoice",["menu","newspaper","calendar"],"Checking receipts prevents errors.")
H('484.d.11.F',4,"A shipment arrives with a lot number that matches a recall. The technician should set it aside and tell the:","pharmacist",["delivery driver only","customers","bank"],"Recalled lots must not be dispensed.")
H('484.d.12.A',3,"Hand washing before handling medicines should last at least:","20 seconds",["2 seconds","5 seconds","1 hour"],"20 seconds is the standard.")
H('484.d.12.A',4,"Counting trays are cleaned between uses to prevent:","cross-contamination",["static","noise","fading"],"Residue can contaminate other drugs.")
H('484.d.12.B',3,"A material safety data sheet tells workers about the hazards of:","chemicals",["paychecks","schedules","holidays"],"SDS describes chemical hazards.")
H('484.d.12.B',4,"In a fire, the pharmacy team should follow the posted:","evacuation plan",["sales plan","menu","price list"],"Emergency plans protect people.")
