H('484.d.12.F',3,"Documenting allergies protects a patient from receiving a drug that could cause a:","reaction",["discount","refund","reward"],"Allergy records prevent harm.")
H('484.d.12.F',4,"Each time a patient picks up a prescription, the technician should ask whether any allergies have:","changed",["expired","been sold","been delivered"],"Allergy lists must stay current.")

# ---- 485 Pharmacology ----
H('485.d.1.A',3,"The branch of pharmacology that studies what a drug does to the body is:","pharmacodynamics",["pharmacokinetics","toxicology only","pharmacy law"],"Pharmacodynamics = drug effects.")
H('485.d.1.A',4,"Absorption, distribution, metabolism, and excretion of a drug are studied in:","pharmacokinetics",["pharmacodynamics","pharmacognosy","posology"],"Pharmacokinetics = what the body does to the drug.")
H('485.d.1.B',3,"An accredited journal article about a clinical trial is an example of a source of drug:","information",["packaging","advertising only","gossip"],"Journals provide evidence.")
H('485.d.1.B',4,"A drug monograph that lists approved uses, doses, and warnings is also called the package:","insert",["bag","tag","box top"],"Package inserts describe the drug.")
H('485.d.1.C',3,"A research article reporting original study results is a primary reference, while a textbook that summarizes many studies is a:","tertiary reference",["rumor","poster","primary source again"],"Textbooks are tertiary.")
H('485.d.1.C',4,"An index that helps find articles by topic without giving the full study is a secondary:","reference",["recipe","map","label"],"Indexes point to primary articles.")
H('485.d.1.D',3,"The first pharmacists in ancient times prepared remedies from plants, minerals, and:","animal products",["computers","plastics","radios"],"Early medicine used natural materials.")
H('485.d.1.D',4,"Alexander Fleming's 1928 discovery of penicillin began the era of modern:","antibiotics",["anesthetics","vaccines for polio","vitamins"],"Penicillin was the first antibiotic.")
H('485.d.1.E',3,"A drug advertisement states '9 out of 10 patients felt better' but does not say how many were studied. This claim lacks:","supporting data",["color","humor","music"],"Ads should be checked against data.")
H('485.d.1.E',4,"Promotional materials are designed to persuade, so a technician should compare claims to unbiased:","clinical studies",["slogans","jingles","coupons"],"Check claims against evidence.")
H('485.d.1.F',3,"When a medicine has a very high price, some patients may skip doses, which is a societal impact of drug:","cost",["color","smell","weight"],"High costs affect adherence.")
H('485.d.1.F',4,"A drug that is made by many companies after the patent ends usually has a lower price than the original brand because of:","competition",["tradition","distance","weather"],"Generic competition lowers cost.")
H('485.d.1.G',3,"The development of vaccines has reduced deaths from diseases like measles, showing the benefits of scientific:","research",["rumor","folklore","gossip"],"Research improves health.")
H('485.d.1.G',4,"New drugs are tested in phases of clinical trials to ensure they are both safe and:","effective",["colorful","cheap","fast"],"Trials test safety and efficacy.")
H('485.d.2.A',3,"A person who wants to dispense medicines in a hospital could become a pharmacist or a pharmacy:","technician",["pilot","plumber","carpenter"],"Pharmacology careers include technicians.")
H('485.d.2.A',4,"A career path that involves researching new drugs in a lab is a pharmaceutical:","scientist",["driver","chef","clerk"],"Researchers develop drugs.")
H('485.d.2.B',3,"On a pharmacy team, the person who gives final approval of a filled prescription is the:","pharmacist",["technician","cashier","driver"],"Pharmacists verify.")
H('485.d.2.B',4,"Pharmacy technicians support pharmacists by handling tasks such as counting, labeling, and:","data entry",["diagnosing","prescribing","surgery"],"Technicians do technical tasks.")
H('485.d.2.C',3,"A growing area in which pharmacists use genes to choose a drug and dose is called:","personalized medicine",["herbal tea","fast food","aroma care"],"Pharmacogenomics guides therapy.")
H('485.d.2.C',4,"Pharmacy jobs in nuclear pharmacy handle drugs that contain small amounts of radioactive:","material",["ink","sugar","fabric"],"Nuclear pharmacy prepares radiopharmaceuticals.")
H('485.d.3.A',3,"A wrong drug given to a patient is a medical error that can result in injury or:","death",["savings","vacation","lunch"],"Errors can have serious consequences.")
H('485.d.3.A',4,"Common causes of medical errors include poor communication, fatigue, and unclear:","handwriting",["weather","lighting at night","sports"],"Illegible handwriting causes mistakes.")
H('485.d.3.B',3,"Failing to give the care a reasonable professional would give is called:","negligence",["donation","hospitality","luck"],"Negligence is a failure of duty.")
H('485.d.3.B',4,"Harm from a professional's improper conduct that can lead to a lawsuit is called:","malpractice",["generosity","kindness","audit"],"Malpractice is professional negligence.")
H('485.d.3.C',3,"The ethical principle of doing good for the patient is:","beneficence",["negligence","autonomy","justice"],"Beneficence means doing good.")
H('485.d.3.C',4,"Respecting a patient's right to make their own decisions about care is the principle of:","autonomy",["beneficence","justice","fidelity"],"Autonomy is self-determination.")
H('485.d.3.D',3,"A policy that protects a pharmacist from claims of errors is called professional liability:","insurance",["patent","license","audit"],"Liability coverage protects professionals.")
H('485.d.3.D',4,"A technician is responsible for staying within the limits of their training to avoid professional:","liability",["holiday","reward","bonus"],"Liability comes from acts outside scope.")
H('485.d.4.A',3,"The word root 'cardi' relates to the:","heart",["lung","kidney","liver"],"Cardi- means heart.")
H('485.d.4.A',4,"The suffix '-itis' means:","inflammation",["removal","study","pain relief"],"-itis = inflammation.")
H('485.d.4.B',3,"A drug that prevents vomiting is called an anti-:","emetic",["pyretic","tussive","biotic"],"Emetic relates to vomiting.")
H('485.d.4.B',4,"A diuretic increases the production of:","urine",["saliva","blood","bile"],"Diuretics increase urine output.")
H('485.d.4.C',3,"Breaking the word 'hypotension' into parts, 'hypo-' means:","below normal",["above normal","around","without"],"Hypo = under.")
H('485.d.4.C',4,"In 'gastroenterology', 'gastro' refers to the:","stomach",["brain","skin","bone"],"Gastro = stomach.")
H('485.d.4.D',3,"A technician explains to a patient that 'hypertension' means:","high blood pressure",["low blood sugar","a stomachache","a cough"],"Use plain words for patients.")
H('485.d.4.D',4,"Instead of saying 'take this drug orally,' a technician can say 'take this by:'","mouth",["needle","patch","ear drop"],"Plain language helps understanding.")
H('485.d.5.A',3,"A dose of 5 mg per kg for a 40 kg patient is:","200 mg",["45 mg","8 mg","20 mg"],"5 x 40 = 200.")
H('485.d.5.A',4,"If a 250 mg per 5 mL suspension is available, how many mL contain 500 mg?","10 mL",["5 mL","2.5 mL","25 mL"],"500 / 250 x 5 = 10.")
H('485.d.5.B',3,"2.5 grams converted to milligrams is:","2500 mg",["250 mg","25 mg","25000 mg"],"Multiply by 1000.")
H('485.d.5.B',4,"750 mL converted to liters is:","0.75 L",["7.5 L","75 L","0.075 L"],"Divide by 1000.")
H('485.d.5.C',3,"One ounce is about how many milliliters?","30 mL",["5 mL","15 mL","100 mL"],"1 fl oz = 30 mL.")
H('485.d.5.C',4,"A patient weighing 110 lb weighs about how many kilograms? (1 kg = 2.2 lb)","50 kg",["25 kg","242 kg","100 kg"],"110 / 2.2 = 50.")
H('485.d.5.D',3,"Studies show that patients who do not take medicine as directed have poor patient:","compliance",["luck","grooming","income"],"Compliance means following directions.")
H('485.d.5.D',4,"A statistic from a small sample may not apply to everyone, which is a limitation of:","sample size",["font","price","color"],"Samples limit generalization.")
H('485.d.6.A',3,"Tablets, capsules, and powders are examples of solid:","dosage forms",["fabrics","recipes","tools"],"Dosage forms vary.")
H('485.d.6.A',4,"A drug placed on the skin that is absorbed slowly over days is a transdermal:","patch",["tablet","syrup","pill"],"Patches deliver steady doses.")
H('485.d.6.B',3,"Tylenol is a brand name for the generic drug:","acetaminophen",["ibuprofen","aspirin","naproxen"],"Brand to generic.")
H('485.d.6.B',4,"Advil is a brand name for the generic drug:","ibuprofen",["acetaminophen","aspirin","naproxen"],"Advil = ibuprofen.")
H('485.d.6.C',3,"An elixir is a sweet liquid that contains alcohol, while a syrup is a thick sweet:","liquid with sugar",["powder","tablet","patch"],"Syrups contain sugar.")
H('485.d.6.C',4,"The term 'enteric-coated' means the tablet is coated to survive stomach acid and dissolve in the:","intestine",["mouth","eye","ear"],"Enteric coating delays release.")
H('485.d.6.D',3,"An unwanted but expected effect of a drug is a(n):","side effect",["therapeutic effect","placebo","brand name"],"Side effects are secondary.")
H('485.d.6.D',4,"A harmful drug effect that is not expected at normal doses is a(n):","adverse reaction",["therapeutic effect","order","refill"],"Adverse reactions are dangerous.")
H('485.d.6.E',3,"Beta blockers work by blocking receptors to slow the:","heart rate",["growth of hair","digestion only","hearing"],"Beta blockers reduce heart rate.")
H('485.d.6.E',4,"Allergy pills of this type relieve sneezing and itching by blocking the effects of a chemical released in allergic reactions called:","histamine",["insulin","cortisol","oxygen"],"Antihistamines block histamine.")
H('485.d.6.F',3,"As the dose of a drug increases, the effect usually increases up to a point, which is the dose-response:","relationship",["parade","budget","refill"],"Dose and response are linked.")
H('485.d.6.F',4,"The dose at which a drug is effective in 50 percent of people is the effective dose 50, while the dose that is lethal in 50 percent is the:","lethal dose 50",["safe dose 50","minimum dose 50","bonus dose"],"LD50 measures toxicity.")
H('485.d.6.G',3,"A technician practices drug safety by checking expiration dates and storing medicines away from:","children",["pharmacists","labels","registers"],"Keep medicines from kids.")
H('485.d.6.G',4,"Medicines such as insulin lose strength if they are stored at the wrong:","temperature",["price","color","noise"],"Storage affects potency.")
H('485.d.7.A',3,"Electronic prescribing, barcode scanning, and robotics are all examples of pharmacy:","technology",["decor","uniforms","carpeting"],"Technology supports workflow.")
H('485.d.7.A',4,"An electronic health record shares a patient's medications with the pharmacy to improve:","safety",["lunch","decor","parking"],"EHRs support safe care.")
H('485.d.7.B',3,"A barcode scan at the time of filling confirms the correct drug and reduces:","errors",["customers","staff","hours"],"Scanning improves accuracy.")
H('485.d.7.B',4,"Automated refill reminders help patients take medicine regularly, which improves:","adherence",["profit only","traffic","signage"],"Reminders help adherence.")
H('485.d.7.C',3,"A balance used to weigh compounding ingredients must be regularly calibrated to ensure:","accuracy",["noise","color","scent"],"Calibration keeps it accurate.")
H('485.d.7.C',4,"Cleaning a counting tray after counting a drug that leaves residue prevents:","contamination",["inflation","fading","noise"],"Residue contaminates.")
H('485.d.8.A',3,"Workplace safety standards in a pharmacy are set to protect employees from hazards such as chemicals and:","sharps",["music","windows","clocks"],"Safety standards cover hazards.")
H('485.d.8.A',4,"The agency that sets and enforces workplace safety standards in the United States is OSHA, the Occupational Safety and Health:","Administration",["Alliance","Association","Agreement"],"OSHA enforces standards.")
H('485.d.8.B',3,"When local and federal rules differ, a pharmacy should follow the:","strictest rule",["loosest rule","oldest rule","shortest rule"],"Stricter standards protect more.")
H('485.d.8.B',4,"State boards of pharmacy publish rules for pharmacies, and the pharmacy must follow them in addition to federal:","law",["fashion","suggestions","menus"],"Both apply.")
H('485.d.8.C',3,"Skipping steps like double-checking the label can lead to unsafe practice and:","patient harm",["bonuses","awards","discounts"],"Unsafe practice harms patients.")
H('485.d.8.C',4,"A pharmacy that repeatedly ignores safety rules may face fines or loss of its:","license",["parking","uniforms","mail"],"Consequences can be severe.")
H('485.d.8.D',3,"When giving client care, a technician follows procedures that protect both the patient and the:","caregiver",["calendar","budget","radio"],"Safe procedures protect both.")
H('485.d.8.D',4,"Using sharps safely means never recapping a used needle and disposing of it in a:","sharps container",["trash can","drawer","pocket"],"Sharps containers prevent sticks.")

# ---- 486 Microbiology ----
H('486.d.1.A',3,"A technician notices that milk left out overnight smells sour and asks what organisms caused the change. This is forming a:","scientific question",["recipe","final grade","safety rule"],"Observations lead to questions.")
H('486.d.1.A',4,"Before culturing a throat swab, the lab states what is unknown and what will be measured. This step is defining the:","problem",["conclusion","schedule","budget"],"Problems come first.")
H('486.d.1.B',3,"Growing the same bacteria on plates with and without an antibiotic compares two:","conditions",["colors","breeds","papers"],"Comparative design.")
H('486.d.1.B',4,"A plate that is left untreated so it can be compared with treated plates is the:","control",["variable","sample","hypothesis"],"Controls provide a baseline.")
H('486.d.1.C',3,"Used culture plates must be disposed of by sterilizing them in a(n):","autoclave",["freezer","toaster","oven mitt"],"Autoclaves kill microbes.")
H('486.d.1.C',4,"A spill of bacterial culture on the bench is first covered with paper towels soaked in:","disinfectant",["water only","soap bubbles","sand"],"Disinfect spills.")
H('486.d.1.D',3,"The tool used to magnify tiny microbes on a slide is a:","microscope",["telescope","scale","ruler"],"Microscopes magnify.")
H('486.d.1.D',4,"A sterile loop used to transfer bacteria to a plate in a zigzag pattern is called a(n):","inoculating loop",["syringe","scalpel","pipe"],"Loops spread inoculum.")
H('486.d.1.E',3,"The width of a bacterial cell is measured in micrometers, a unit in the:","International System of Units",["imperial yards","US customary system","random units"],"SI includes micrometers.")
H('486.d.1.E',4,"A colony measuring 3 mm is how many micrometers wide?","3000",["30","300","0.3"],"1 mm = 1000 micrometers.")
H('486.d.1.F',3,"A graph of bacterial growth over time is a way to organize:","quantitative data",["jokes","opinions","names"],"Graphs show counts.")
H('486.d.1.F',4,"A table comparing colony color, shape, and size on different plates organizes:","qualitative data",["only counts","only prices","only dates"],"Descriptions are qualitative.")
H('486.d.1.G',3,"A drawing that shows how a virus infects a cell is a:","model",["law","theory only","guess"],"Models represent processes.")
H('486.d.1.G',4,"A computer simulation of how resistance spreads through a bacterial population is used to represent a:","system",["recipe","budget","banner"],"Models explain systems.")
H('486.d.1.H',3,"A testable explanation proposed before an experiment is a:","hypothesis",["law","fact","theory"],"A hypothesis is tentative.")
H('486.d.1.H',4,"A description of what always happens under certain conditions, such as the law of gravity, is a scientific:","law",["hypothesis","opinion","rumor"],"Laws describe patterns.")
H('486.d.2.A',3,"A model of a bacterium drawn much larger than its real size has a limitation in:","scale",["flavor","humor","price"],"Models are not to scale.")
H('486.d.2.A',4,"An advantage of a plate-based model of infection is that it can be repeated cheaply, but a limitation is that it lacks a:","host's immune response",["lid","label","sticker"],"Models omit complexity.")
H('486.d.2.B',3,"A student sees that colony counts increase every hour until food runs out. This is a growth:","pattern",["accident","error","rumor"],"Patterns are trends.")
H('486.d.2.B',4,"Average colony count and range are examples of statistical:","features",["errors","guesses","labels"],"Statistics describe data.")
H('486.d.2.C',3,"If one bacterium divides every 20 minutes, after 60 minutes there are:","8 bacteria",["3 bacteria","6 bacteria","4 bacteria"],"2 x 2 x 2 = 8.")
H('486.d.2.C',4,"If a culture starts with 100 cells and doubles 4 times, the total is:","1600",["400","800","200"],"100 x 16 = 1600.")
H('486.d.2.D',3,"Judging whether a new sterilization method worked as intended means evaluating an engineering:","design",["menu","slogan","tune"],"Designs are tested.")
H('486.d.2.D',4,"Comparing two hand-washing methods by counting remaining bacteria on hands evaluates an experimental:","design",["symptom","recipe","recital"],"Results evaluate designs.")
H('486.d.3.A',3,"A student explains why mold grew on bread and supports it with moisture readings and models. This explanation is supported by:","data",["gossip","slogans","jokes"],"Evidence supports explanations.")
H('486.d.3.A',4,"To propose a solution for stopping bacterial spread in a lab, a student would cite results of tests with different:","disinfectants",["pencils","chairs","windows"],"Solutions rely on data.")
H('486.d.3.B',3,"A group of students presents the results of their culture experiment to the class. This is sharing results through:","communication",["secrecy","delay","avoidance"],"Scientists communicate.")
H('486.d.3.B',4,"Dividing up tasks like plating, counting, and recording is an example of:","collaboration",["competition","confusion","conflict"],"Teams collaborate.")
H('486.d.3.C',3,"In a scientific argument about a study, a respectful reply is to ask for the:","evidence",["rank","age","salary"],"Argue with evidence.")
H('486.d.3.C',4,"When a classmate challenges your conclusion, a good response is to explain how your results support it and be open to:","other interpretations",["no feedback","winning at all costs","silence"],"Open-mindedness is key.")
H('486.d.4.A',3,"A claim that a cream kills all germs is evaluated by checking whether the study has a:","control group",["catchy name","pretty label","long title"],"Controls are needed.")
H('486.d.4.A',4,"A critic points out that a bacterial experiment was done only once. This is a weakness in the study's:","replication",["font","title","color"],"Repeat to confirm.")
H('486.d.4.B',3,"Louis Pasteur's experiments with flasks disproved spontaneous generation and supported the idea that microbes come from:","other microbes",["nothing","rocks","wind only"],"Life comes from life.")
H('486.d.4.B',4,"Robert Koch's postulates provide steps to prove that a specific microbe causes a specific:","disease",["recipe","color","song"],"Koch linked germs to illness.")
H('486.d.4.C',3,"A student who wants to become a medical laboratory scientist can learn about the career from a professional:","organization",["gossip column","comic strip","toy shop"],"Associations offer career info.")
H('486.d.4.C',4,"A museum of medical history is a resource for exploring how scientists discovered:","microorganisms",["new shoes","music styles","road maps"],"Museums teach history.")
H('486.d.5.A',3,"Antonie van Leeuwenhoek was among the first people to observe microbes using a simple:","microscope",["telescope","camera","radio"],"He saw 'animalcules'.")
H('486.d.5.A',4,"Joseph Lister reduced deaths after surgery by using carbolic acid to practice:","antisepsis",["inflation","distillation","penmanship"],"Lister pioneered antiseptics.")
H('486.d.5.B',3,"The agency that tracks and helps control the spread of infectious disease in the United States is the Centers for Disease:","Control and Prevention",["Cure and Pricing","Care and Parking","Counting and Production"],"CDC tracks disease.")
H('486.d.5.B',4,"The agency that regulates the safety of food, drugs, and medical devices is the:","Food and Drug Administration",["Fire Department","Forest Service","Federal Reserve"],"FDA regulates products.")
H('486.d.6.A',3,"A tool that asks yes-or-no questions about an organism's traits to identify it is a:","dichotomous key",["bar graph","pie chart","road map"],"Dichotomous = two choices.")
H('486.d.6.A',4,"In a dichotomous key, the first question 'Is the cell wall present?' leads to two:","choices",["colors","sizes","songs"],"Each step has two paths.")
H('486.d.6.B',3,"In a Gram stain, Gram-positive bacteria appear:","purple",["pink","green","yellow"],"Thick peptidoglycan holds crystal violet.")
H('486.d.6.B',4,"Gram-negative bacteria stain pink or red because they have a thin wall and an outer:","membrane",["shell","fur","scale"],"Outer membrane differs.")
H('486.d.6.C',3,"A protein that speeds up a chemical reaction in a microbe is a(n):","enzyme",["hormone","antibody","wall"],"Enzymes are biological catalysts.")
H('486.d.6.C',4,"Water moving across a bacterial cell membrane because of a concentration difference is called:","osmosis",["mitosis","meiosis","digestion"],"Osmosis moves water.")
H('486.d.6.D',3,"A lab machine that can make millions of copies of a DNA segment is a polymerase chain reaction:","thermal cycler",["blender","oven","fridge"],"PCR amplifies DNA.")
H('486.d.6.D',4,"Technology that separates DNA fragments by size using an electric current is gel:","electrophoresis",["filtration","distillation","incubation"],"Gel electrophoresis separates fragments.")
H('486.d.6.E',3,"A nutrient mixture used to grow microbes in a dish is called:","agar",["cotton","gauze","foil"],"Agar is a growth medium.")
H('486.d.6.E',4,"A medium that contains blood to show whether bacteria break down red blood cells is a(n):","blood agar plate",["water bottle","paper towel","sand tray"],"Blood agar shows hemolysis.")
H('486.d.6.F',3,"Microbes that live on the skin or in the gut without causing disease are the normal:","flora",["fauna","pathogens","toxins"],"Normal flora are harmless residents.")
H('486.d.6.F',4,"E. coli is a normal inhabitant of the human:","intestine",["eye","heart","kidney"],"E. coli lives in the gut.")
H('486.d.6.G',3,"A microbe that usually does not cause illness but can in a person with a weak immune system is an:","opportunistic pathogen",["antibody","vitamin","enzyme"],"Opportunists take advantage.")
H('486.d.6.G',4,"Streptococcus pyogenes is the cause of strep throat, a disease classified as:","bacterial",["viral","fungal","parasitic"],"Strep is bacterial.")
H('486.d.6.H',3,"A visible group of cells grown from a single bacterium on a plate is a:","colony",["membrane","gel","drop"],"Colonies come from one cell.")
H('486.d.6.H',4,"Describing a colony's shape, edge, and color is a record of its:","morphology",["pricing","ownership","history"],"Morphology means form.")
H('486.d.6.I',3,"A report that shows which antibiotics kill an isolated bacterium is a culture and:","sensitivity report",["billing record","sales report","stock report"],"C and S guides therapy.")
H('486.d.6.I',4,"If a culture and sensitivity report lists a drug as 'resistant,' then that drug will probably:","not work",["work best","be cheaper","be flavored"],"Resistant means ineffective.")
H('486.d.7.A',3,"For an infection to spread, a pathogen must leave a reservoir, be transmitted, and enter a susceptible:","host",["bank","lab","store"],"Chain of infection.")
H('486.d.7.A',4,"Droplets from a sneeze that infect someone nearby are an example of a mode of:","transmission",["recovery","storage","sales"],"Transmission spreads disease.")
H('486.d.7.B',3,"Tuberculosis is caused by bacteria, ringworm is caused by a fungus, and influenza is caused by a:","virus",["bacterium","protozoan","worm"],"Flu is viral.")
H('486.d.7.B',4,"Malaria is caused by a single-celled:","parasite",["fungus","virus","bacterium"],"Plasmodium is a protozoan.")
H('486.d.7.C',3,"White blood cells that engulf germs are part of the body's defense called the immune:","response",["menu","price","budget"],"Immune cells respond.")
H('486.d.7.C',4,"Proteins made by the body that attach to specific invaders are:","antibodies",["hormones","enzymes","fibers"],"Antibodies target antigens.")
H('486.d.7.D',3,"On a plate with antibiotic discs, a clear ring around a disc shows the drug stopped bacteria from growing, called a zone of:","inhibition",["growth","color","heat"],"Zone of inhibition shows effect.")
H('486.d.7.D',4,"A larger zone of inhibition around a disc generally means the bacteria are more:","susceptible",["resistant","numerous","colorful"],"Bigger zone = more sensitive.")
H('486.d.7.E',3,"Travel, crowded living, and poor sanitation can contribute to the emergence of:","new infectious diseases",["new snacks","stock sales","fashion"],"Social factors matter.")
H('486.d.7.E',4,"A disease that was nearly gone and has returned is described as:","reemerging",["emerging only","chronic","extinct"],"Reemerging diseases return.")
H('486.d.7.F',3,"MRSA is resistant to methicillin and many other:","antibiotics",["vaccines","vitamins","enzymes"],"MRSA resists antibiotics.")
H('486.d.7.F',4,"Overusing antibiotics encourages the survival of the most:","resistant bacteria",["sensitive bacteria","viruses only","vitamins"],"Resistant strains survive.")
H('486.d.7.G',3,"The World Health Organization monitors disease worldwide and sets:","health guidelines",["menu prices","sports rules","fashion trends"],"WHO sets guidelines.")
H('486.d.7.G',4,"In the United States, outbreaks of reportable diseases are tracked by local and state health departments and the:","CDC",["NFL","NASA","NBA"],"CDC collects reports.")
H('486.d.8.A',3,"Treating all blood and body fluids as if they could spread infection is called standard:","precautions",["recipes","rewards","reminders"],"Standard precautions.")
H('486.d.8.A',4,"A lab worker with a cut on the hand should cover it with a waterproof bandage and wear:","gloves",["rings","bracelets","a scarf"],"Protect broken skin.")
H('486.d.8.B',3,"The four biosafety levels classify labs according to the risk of the microbes handled, with BSL-1 being the:","lowest risk",["highest risk","most expensive","largest"],"BSL-1 is lowest.")
H('486.d.8.B',4,"Mouth pipetting is never allowed because it can cause you to swallow:","a sample",["a pencil","a ruler","a plate"],"Use pipette aids.")
H('486.d.8.C',3,"Gloves, goggles, and a lab coat are examples of personal protective:","equipment",["opinions","schedules","recipes"],"PPE protects workers.")
H('486.d.8.C',4,"After a lab session, you should remove your gloves and then wash your hands with:","soap and water",["dry paper","sand","juice"],"Hand hygiene follows PPE removal.")
H('486.d.8.D',3,"Surgical instruments are sterilized using steam under pressure in an:","autoclave",["oven","fridge","toaster"],"Autoclaves use pressure.")
H('486.d.8.D',4,"To confirm an autoclave worked, labs use indicator tape or biological indicators containing resistant:","spores",["leaves","seeds","crystals"],"Spores show effectiveness.")
H('486.d.8.E',3,"A chemical that can be safely used on living tissue to slow microbes is an:","antiseptic",["disinfectant for floors","bleach","detergent"],"Antiseptics are for skin.")
H('486.d.8.E',4,"A chemical used on surfaces and objects, not skin, to kill microbes is a:","disinfectant",["antiseptic","vitamin","antibiotic"],"Disinfectants are for objects.")

# ---- 487 Health Informatics ----
H('487.d.1.A',3,"A system that stores and manages a patient's medical history in digital form is a(n):","electronic health record",["paper chart","phone book","recipe card"],"EHRs store records digitally.")
H('487.d.1.A',4,"A hospital's laboratory information system is designed specifically to manage:","lab test orders and results",["parking","payroll only","menus"],"LIS handles lab data.")
H('487.d.1.B',3,"Health information systems help administrators track patient visits, billing, and hospital:","resources",["gossip","fashion","music"],"Systems support administration.")
H('487.d.1.B',4,"Dashboards that show how many beds are open help hospital staff make decisions about:","patient flow",["wardrobe","landscaping","art"],"Data supports operations.")
H('487.d.2.A',3,"Software that lets users create, store, and retrieve data in a database is a database:","management system",["decoration","alarm","hobby"],"A DBMS organizes data.")
H('487.d.2.A',4,"A database management system lets many users search and update records while controlling who may:","access them",["delete the building","print money","change the weather"],"DBMS controls access.")
H('487.d.2.B',3,"Planning how data will be organized in a database before building it is the purpose of data:","modeling",["storage","erasing","guessing"],"Modeling plans structure.")
H('487.d.2.B',4,"A data model helps designers show how pieces of information are connected so that the database is easier to:","use and maintain",["hide","ignore","delete"],"Models clarify design.")
H('487.d.2.C',3,"The customary first step in data modeling is to identify the data that must be:","stored",["ignored","erased","hidden"],"Start with requirements.")
H('487.d.2.C',4,"After identifying the data needed, designers create diagrams that show the entities and then build the:","database structure",["vending machine","menu","calendar"],"Modeling moves from concept to implementation.")
H('487.d.2.D',3,"In a patient table, a person such as 'patient' is an entity, and a piece of information like 'birth date' is an:","attribute",["entity","relationship","server"],"Attributes describe entities.")
H('487.d.2.D',4,"The link between a patient and the doctors who treat that patient is a:","relationship",["attribute","password","backup"],"Relationships connect entities.")
H('487.d.2.E',3,"A hospital stores its records in a system owned and used within the organization, called an organizational:","database",["bookshelf","stock market","toolbox"],"Organizations keep databases.")
H('487.d.2.E',4,"A database stored on remote servers and accessed over the internet is a(n):","cloud database",["paper database","hallway database","tape rack"],"Cloud storage is remote.")
H('487.d.3.A',3,"Making sure that health data is not changed without permission is called data:","integrity",["gossip","delay","display"],"Integrity means accuracy and protection.")
H('487.d.3.A',4,"Using unique usernames and passwords helps keep health data:","secure",["public","random","shared"],"Security needs authentication.")
H('487.d.3.B',3,"Information that a nurse enters in a patient's chart should be accurate, complete, and:","timely",["optional","colorful","creative"],"Data should be timely.")
H('487.d.3.B',4,"Backing up health records regularly helps protect them from loss due to:","system failure",["rain on the sidewalk","a new hairstyle","a day off"],"Backups protect data.")
H('487.d.4.A',3,"The shift from paper charts to digital records has grown rapidly because it can improve patient safety and:","efficiency",["clutter","delays","errors"],"EHRs support efficiency.")
H('487.d.4.A',4,"A major benefit of an EHR is that a patient's information can be accessed by authorized providers at:","multiple locations",["only one desk","only at night","only on paper"],"EHRs increase access.")
H('487.d.4.B',3,"The federal HITECH Act encouraged health care providers to adopt electronic:","health records",["menus","uniforms","recipes"],"HITECH promoted EHRs.")
H('487.d.4.B',4,"Before EHRs became common, patient information was mostly kept on:","paper",["tape","hard drives","clouds"],"Paper charts came first.")
H('487.d.4.C',3,"A functional requirement of an EHR is that it must let providers enter orders, view results, and:","document care",["throw away data","hide notes","change patients"],"Documentation is core.")
H('487.d.4.C',4,"A basic EHR requirement is that every action in the record is logged with a:","user and time stamp",["joke","weather note","color code"],"Audit trails are required.")
H('487.d.4.D',3,"The ability of different health IT systems to exchange and use information is called:","interoperability",["isolation","redundancy","compression"],"Systems must communicate.")
H('487.d.4.D',4,"Interoperability is important because a patient may be treated by providers who use different:","software systems",["floors","uniforms","parking decks"],"Interoperability shares data.")
H('487.d.5.A',3,"The law that protects the privacy of patient health information is the Health Insurance Portability and:","Accountability Act",["Allocation Act","Assistance Act","Approval Act"],"HIPAA protects PHI.")
H('487.d.5.A',4,"Under HIPAA, patient information may be shared without a signed release for treatment, payment, and health care:","operations",["advertising","gossip","parties"],"TPO exceptions.")
H('487.d.5.B',3,"Billing for services that were never provided is insurance:","fraud",["abuse","rebate","audit"],"Fraud is intentional deception.")
H('487.d.5.B',4,"Billing practices that are inconsistent with sound practice but not intentionally deceptive are insurance:","abuse",["fraud","coding","adjudication"],"Abuse is not necessarily intentional.")
H('487.d.5.C',3,"CPT codes describe the medical procedures and services that were:","performed",["rumored","imagined","canceled"],"CPT codes identify services.")
H('487.d.5.C',4,"A claim links a CPT code with a diagnosis code to show the service was medically:","necessary",["optional","funny","free"],"Linking shows necessity.")
H('487.d.5.D',3,"The ICD-10-CM code system is used to code a patient's:","diagnosis",["address","favorite food","height only"],"ICD codes diagnoses.")
H('487.d.5.D',4,"To select the correct ICD-10-CM code, a coder starts with the diagnosis in the physician's documentation and looks it up in the:","alphabetic index",["phone book","dictionary of slang","street map"],"Index leads to the tabular list.")
H('487.d.5.E',3,"HCPCS codes have two levels: Level I is CPT codes, and Level II covers supplies and services such as:","ambulance rides",["haircuts","movie tickets","groceries"],"Level II covers non-physician services.")
H('487.d.5.E',4,"Level II HCPCS codes begin with a:","letter",["number","symbol","space"],"Level II codes start with a letter.")
H('487.d.5.F',3,"Incorrect medical coding can cause claims to be:","denied",["admired","celebrated","framed"],"Coding errors cause denials.")
H('487.d.5.F',4,"Accurate coding helps ensure that the provider receives the proper:","payment",["trophy","promotion","vacation"],"Coding affects reimbursement.")
H('487.d.6.A',3,"An organization that processes Medicare claims for a region is called a fiscal:","intermediary",["customer","patient","vendor"],"FIs process claims.")
H('487.d.6.A',4,"A fiscal intermediary acts as a link between the government program and the:","health care provider",["school","grocery store","bank teller"],"FIs connect providers and payers.")
H('487.d.6.B',3,"The federal health insurance program primarily for people age 65 and older is:","Medicare",["Medicaid","TRICARE","CHIP"],"Medicare covers seniors.")
H('487.d.6.B',4,"The joint federal and state program that helps cover medical costs for people with low income is:","Medicaid",["Medicare","TRICARE","COBRA"],"Medicaid is income-based.")
H('487.d.6.C',3,"The health care program for active-duty military members and their families is:","TRICARE",["Medicaid","Medicare","CHIP"],"TRICARE serves the military.")
H('487.d.6.C',4,"CHAMPVA provides health care benefits to dependents of veterans who are:","permanently and totally disabled",["healthy","retired from school","uninsured only"],"CHAMPVA serves certain families.")
H('487.d.6.D',3,"A health insurance claim for an injury that happened on the job is usually handled under:","workers' compensation",["Medicare Part D","dental insurance","auto insurance"],"Work injuries go to workers' comp.")
H('487.d.6.D',4,"In a workers' compensation case, the employer is usually required to be notified of the injury within a set:","time period",["season","century","hour of the day"],"Deadlines apply.")
H('487.d.6.E',3,"The standard paper claim form used by many professional providers is the:","CMS-1500",["IRS-1040","W-2","UB-04 for hospitals only"],"CMS-1500 is the professional claim.")
H('487.d.6.E',4,"On the CMS-1500 form, Block 21 lists the ICD codes. This block records the patient's medical:","diagnosis",["address","employer","birthday"],"Block 21 is diagnoses.")
H('487.d.6.F',3,"Claims can be transmitted electronically through direct entry, a clearinghouse, or a payer:","portal",["fax only","carrier pigeon","bulletin board"],"Portals transmit claims.")
H('487.d.6.F',4,"A company that checks claims for errors and forwards them to insurers is a:","clearinghouse",["newsstand","greenhouse","warehouse"],"Clearinghouses scrub claims.")

# ---- 488 Medical Billing and Coding ----
H('488.d.1.A',3,"A job that involves assigning codes to diagnoses and procedures is a medical:","coder",["welder","pilot","chef"],"Coders assign codes.")
H('488.d.1.A',4,"A professional who submits claims and follows up on unpaid insurance claims works in medical:","billing",["surgery","dentistry","radiology"],"Billers manage claims.")
H('488.d.1.B',3,"Coding a service that was not provided in order to be paid more is unethical and is a form of:","fraud",["training","audit","charity"],"Ethical coding is honest.")
H('488.d.1.B',4,"Professional associations publish codes of ethics that require members to code from the physician's:","documentation",["opinions","rumors","guesses"],"Code only what is documented.")
H('488.d.1.C',3,"The American Academy of Professional Coders (AAPC) and the American Health Information Management Association (AHIMA) are professional:","associations",["airlines","banks","stores"],"Both are associations.")
H('488.d.1.C',4,"Earning a credential such as CPC shows that a coder has passed a certification:","exam",["parade","tournament","contest"],"Credentials need exams.")
H('488.d.2.A',3,"The agency that runs Medicare and Medicaid is the Centers for Medicare and Medicaid:","Services",["Systems","Studies","Supplies"],"CMS runs the programs.")
H('488.d.2.A',4,"The federal office that investigates health care fraud and publishes an exclusion list is the Office of Inspector:","General",["Standards","Safety","Services"],"OIG investigates fraud.")
H('488.d.2.B',3,"The Health Insurance Portability and Accountability Act sets rules for the privacy and security of patient:","health information",["bank accounts","school grades","car records"],"HIPAA covers PHI.")
H('488.d.2.B',4,"The False Claims Act imposes penalties on those who knowingly submit false claims to:","the government",["a friend","a neighbor","a pet store"],"FCA covers government payers.")
H('488.d.2.C',3,"A coder who sees that a physician's note does not support a billed service should notify a supervisor, which is an example of ethical:","behavior",["failure","hesitation","delay"],"Report discrepancies.")
H('488.d.2.C',4,"Using a different code than the documentation supports in order to get a higher payment is a legal and ethical:","violation",["shortcut allowed","best practice","courtesy"],"Upcoding is illegal.")
H('488.d.2.D',3,"A medical office follows a written plan to make sure it obeys rules and laws, called a compliance:","program",["menu","contest","party"],"Compliance programs prevent violations.")
H('488.d.2.D',4,"Regular internal audits of claims are one element of a compliance:","plan",["joke","cleanup","trend"],"Audits detect errors.")
H('488.d.2.E',3,"Before a medical office sends a patient's records to another office for non-treatment purposes, it generally needs a signed:","release form",["greeting card","receipt","gift note"],"Authorization is required.")
H('488.d.2.E',4,"A release of information authorization must state what information is being released and to:","whom",["why the doctor is tall","when the sun sets","how far it is"],"Authorizations name the recipient.")
H('488.d.2.F',3,"A patient who signs a document agreeing to a surgery has given:","informed consent",["implied consent","no consent","verbal denial"],"Informed consent is documented.")
H('488.d.2.F',4,"A patient who rolls up a sleeve and offers an arm for a shot is showing:","implied consent",["informed consent","written consent","no consent"],"Actions imply agreement.")
H('488.d.2.G',3,"Sharing patient information inside the office for treatment is a use of information, while sending it to an outside party is a:","disclosure",["deletion","correction","repair"],"Use is internal, disclosure is external.")
H('488.d.2.G',4,"Telling a billing company about a patient's diagnosis so it can file a claim is a disclosure that is permitted for:","payment",["entertainment","gossip","marketing"],"Payment is a permitted purpose.")
H('488.d.2.H',3,"A review of a case in which a provider billed twice for the same visit would look for possible insurance:","fraud or abuse",["bonuses","generosity","luck"],"Duplicate billing is a red flag.")
H('488.d.2.H',4,"Billing for a more expensive service than was performed is called:","upcoding",["downcoding","unbundling only","rounding"],"Upcoding inflates payment.")
H('488.d.3.B',3,"A diagnosis such as depression, ADHD, or autism spectrum disorder is classified in ICD-10-CM among mental, behavioral, and neurodevelopmental:","disorders",["devices","procedures","supplies"],"Chapter F covers these conditions.")
H('488.d.3.B',4,"A coder finds 'bipolar disorder' in a note. This diagnosis is located in the ICD-10-CM chapter for mental, behavioral, and neurodevelopmental:","disorders",["devices","supplies","factors"],"Chapter 5 (F codes) holds mood disorders.")
H('488.d.3.A.i',3,"Coders classify skin conditions such as eczema and burns under the body system called the:","integumentary system",["skeletal system","nervous system","urinary system"],"The skin is the integumentary system.")
H('488.d.3.A.i',4,"The outermost layer of skin that coders may see named in documentation is the:","epidermis",["pericardium","meninges","pleura"],"The epidermis is the outer layer.")
H('488.d.3.A.ii',3,"A fracture of the femur is coded under conditions of the:","skeletal system",["respiratory system","endocrine system","urinary system"],"Bones belong to the skeletal system.")
H('488.d.3.A.ii',4,"The ICD-10-CM chapter for diseases of the musculoskeletal system and connective tissue includes arthritis, which affects the:","joints",["lungs","kidneys","eyes"],"Arthritis is joint inflammation.")
H('488.d.3.A.iii',3,"The system that includes tendons and the biceps, which coders must be able to identify in documentation, is the:","muscular system",["lymphatic system","digestive system","urinary system"],"Muscles move the body.")
H('488.d.3.A.iii',4,"A coder sees 'myalgia' in a note. This term means:","muscle pain",["bone pain","skin rash","blood clot"],"Myo = muscle; algia = pain.")
H('488.d.3.A.iv',3,"A coder assigning a code for a heart attack uses the chapter for diseases of the circulatory system, also called the:","cardiovascular system",["integumentary system","digestive system","skeletal system"],"The heart is part of the cardiovascular system.")
H('488.d.3.A.iv',4,"The medical term for a high blood pressure diagnosis that a coder might find in a note is:","hypertension",["hypotension","tachycardia","arrhythmia"],"Hypertension = high pressure.")
H('488.d.3.A.v',3,"Pneumonia and asthma are coded in the chapter for diseases of the:","respiratory system",["circulatory system","skeletal system","nervous system"],"Lungs are respiratory.")
H('488.d.3.A.v',4,"The term 'dyspnea' in a physician's note means:","difficulty breathing",["chest pain","stomach pain","fast heartbeat"],"Dys = difficult, pnea = breathing.")
H('488.d.3.A.vi',3,"Coders assign codes for appendicitis and ulcers under diseases of the:","digestive system",["urinary system","respiratory system","nervous system"],"The GI tract is digestive.")
H('488.d.3.A.vi',4,"The word 'gastritis' refers to inflammation of the:","stomach lining",["liver","kidney","pancreas only"],"Gastr = stomach.")
H('488.d.3.A.vii',3,"Diabetes mellitus is coded under endocrine, nutritional, and metabolic diseases because it involves the hormone:","insulin",["thyroid only","estrogen","adrenaline"],"Diabetes involves insulin.")
H('488.d.3.A.vii',4,"A gland in the neck that regulates metabolism, coded under the endocrine system, is the:","thyroid",["spleen","liver","tonsil"],"The thyroid is endocrine.")
H('488.d.3.A.viii',3,"A urinary tract infection and kidney stones are coded under diseases of the:","genitourinary system",["respiratory system","digestive system","integumentary system"],"ICD groups them as genitourinary.")
H('488.d.3.A.viii',4,"The organs that filter blood and produce urine, whose diseases coders must recognize, are the:","kidneys",["lungs","lymph nodes","tonsils"],"Kidneys form urine.")
H('488.d.3.A.ix',3,"Pregnancy, childbirth, and the puerperium have their own chapter, and coders must understand the female:","reproductive system",["respiratory system","skeletal system","muscular system"],"Obstetrics is reproductive.")
H('488.d.3.A.ix',4,"The male gland that sits below the bladder and can be coded for enlargement is the:","prostate",["thyroid","pancreas","spleen"],"BPH involves the prostate.")
H('488.d.3.A.x',3,"Codes for stroke, epilepsy, and migraine fall under diseases of the:","nervous system",["digestive system","urinary system","skeletal system"],"The brain is nervous system.")
H('488.d.3.A.x',4,"The sense organs, such as the eye and ear, are included in the ICD-10-CM chapters on diseases of the eye and adnexa and of the:","ear and mastoid process",["foot and ankle","hair and nails","heart and aorta"],"Special senses have chapters.")
H('488.d.4.A',3,"Coding conventions and guidelines help a coder record every billable service, a task called charge:","capture",["theft","delay","erase"],"Charge capture ensures billing.")
H('488.d.4.A',4,"Following the official ICD-10-CM guidelines ensures that diagnosis codes are assigned:","consistently",["randomly","creatively","slowly"],"Guidelines promote consistency.")
H('488.d.4.B',3,"Coding manuals are revised every year, so coders must regularly update their:","code books",["lunch boxes","uniforms","chairs"],"Annual updates occur.")
H('488.d.4.B',4,"ICD-10-CM updates take effect each year on:","October 1",["January 1","July 4","December 25"],"ICD-10-CM updates start in October.")
H('488.d.4.C',3,"Coding to the highest level of specificity means choosing the code with the most:","detail",["cost","letters only","brevity"],"Specific codes are preferred.")
H('488.d.4.C',4,"A coder should assign a code only when the physician has documented the diagnosis, not when it is only:","suspected in outpatient coding",["confirmed","treated","charted"],"Outpatient rules exclude uncertain diagnoses.")
H('488.d.4.D',3,"Diagnosis-related groups classify hospital patients into groups for payment, which is an example of disease:","groupings",["menus","mailings","guesses"],"DRGs group by diagnosis.")
H('488.d.4.D',4,"Combining several related procedure codes into one comprehensive code for billing is called:","bundling",["splitting","unbundling","dropping"],"Bundling combines.")
H('488.d.4.E',3,"A payer will cover a service only if it is medically:","necessary",["optional","decorative","free"],"Medical necessity justifies payment.")
H('488.d.4.E',4,"A national coverage determination from Medicare explains which services are covered based on medical:","necessity",["fashion","opinion","geography"],"NCDs outline necessity.")
H('488.d.4.F',3,"The abbreviation 'NPO' on a chart means:","nothing by mouth",["no pain observed","normal pulse only","next patient overdue"],"NPO = nil per os.")
H('488.d.4.F',4,"The abbreviation 'CHF' stands for congestive:","heart failure",["hearing fault","hip fracture","health fund"],"CHF = congestive heart failure.")
H('488.d.5.A',3,"The process of tracking patient care from scheduling to final payment is revenue cycle:","management",["cleaning","decoration","marketing"],"RCM covers the whole payment process.")
H('488.d.5.A',4,"A medical office's revenue cycle begins at patient scheduling and ends when the account is:","paid in full",["deleted","ignored","framed"],"RCM ends at payment.")
H('488.d.5.B',3,"A plan offered through a person's job is an employer-sponsored plan, while Medicaid is a government:","program",["lottery","coupon","club"],"Government plans exist.")
H('488.d.5.B',4,"A plan that requires patients to choose a primary care provider and get referrals to see specialists is a(n):","HMO",["PPO","HSA","FSA"],"HMOs use gatekeepers.")
H('488.d.5.C',3,"An insurance company that processes Medicare claims for a geographic region is a Medicare Administrative:","Contractor",["Customer","Cashier","Competitor"],"MACs process claims.")
H('488.d.5.C',4,"MACs also educate providers about Medicare rules and process provider:","appeals",["vacations","lunches","uniforms"],"MACs support providers.")
H('488.d.5.D',3,"At check-in, the front desk copies the patient's insurance card and verifies:","eligibility",["height","hobbies","birth month only"],"Verify coverage.")
H('488.d.5.D',4,"Collecting a copay at the time of check-in is part of the:","patient registration process",["lab process","coding process only","billing audit only"],"Front-end collection.")
H('488.d.5.E',3,"The block on the CMS-1500 form that lists the patient's insurance ID number is in the section for:","insured information",["lab results","parking","supplies"],"Insurance info is on the form.")
H('488.d.5.E',4,"When preparing a mock claim, the biller enters the provider's National Provider Identifier, abbreviated:","NPI",["SSN","PIN","ZIP"],"NPI identifies providers.")
H('488.d.5.F',3,"When a patient has two insurance plans, the plan billed first is the:","primary plan",["secondary plan","dental plan","backup plan"],"Primary pays first.")
H('488.d.5.F',4,"The plan that pays after the primary plan has paid is the:","secondary plan",["primary plan","first plan","main plan"],"Secondary covers remaining costs.")
H('488.d.5.G',3,"A document from an insurer explaining how a claim was paid is the remittance:","advice",["rumor","menu","invoice for lunch"],"Remittance advice explains payment.")
H('488.d.5.G',4,"On a remittance advice, the amount the patient owes after the insurer pays is the patient:","responsibility",["bonus","discount","vacation"],"Patient responsibility is the balance.")
H('488.d.5.H',3,"A claim returned because of an error, such as a missing signature, is a(n):","rejection",["payment","approval","bonus"],"Rejections need corrections.")
H('488.d.5.H',4,"A denial because a service is not covered can be addressed by filing a(n):","appeal",["greeting","receipt","reminder"],"Appeals contest denials.")
H('488.d.5.I',3,"A listing that groups unpaid claims by how long they have been outstanding is an aging:","report",["menu","brochure","poster"],"Aging reports show past-due claims.")
H('488.d.5.I',4,"Claims in the 90-plus days column of an aging report are the ones most at risk of not being:","collected",["printed","coded","filed"],"Older accounts are harder to collect.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_72.jsonl"))
